/**
 * United States outline, generated by scripts/build_map.py from Natural Earth
 * 1:110m (public domain). Do not edit by hand -- re-run the script.
 *
 * The projection is equirectangular with a cos(mean latitude) correction,
 * which at the scale of one country is indistinguishable from a proper conic
 * and costs two lines of arithmetic instead of a projection library. `project`
 * places a city on exactly the geometry the outline was drawn with.
 */
export const VIEW_WIDTH = 480;
export const VIEW_HEIGHT = 259;

const MIN_LON = -124.68721;
const MAX_LAT = 49.38905;
const X_SCALE = 0.7955247211;
const SCALE = 10.191701;
const PADDING = 6;

export const OUTLINE_PATH =
  "M21.0,10.0 L245.4,10.0 L245.4,6.0 L248.2,6.0 L252.1,13.3 L273.9,18.7 L300.4,17.1 L328.8,31.4 L347.6,47.2 L351.0,65.3 L343.0,80.5 L346.5,84.6 L376.9,72.5 L375.0,66.4 L378.7,64.7 L394.1,64.7 L409.9,50.7 L437.2,50.6 L444.0,46.0 L455.6,25.8 L467.3,29.7 L467.3,43.6 L474.0,52.7 L448.4,64.1 L442.7,77.9 L445.4,83.3 L448.7,83.5 L447.9,79.8 L450.3,82.1 L449.7,85.0 L419.3,92.2 L433.6,92.2 L417.3,94.0 L415.5,104.7 L409.6,112.5 L404.6,106.8 L408.4,118.0 L401.2,130.1 L403.0,122.7 L398.9,118.8 L397.9,110.4 L398.1,121.2 L392.7,119.6 L398.3,122.9 L403.0,147.0 L397.8,154.6 L375.9,168.0 L357.5,188.9 L357.7,203.2 L367.9,235.4 L365.2,252.5 L358.8,252.5 L354.4,245.7 L345.2,225.2 L346.8,218.4 L338.2,204.3 L326.9,207.3 L316.4,199.5 L290.5,202.0 L292.0,212.2 L261.1,205.8 L249.2,208.9 L229.3,225.7 L229.3,245.7 L226.2,246.0 L214.1,240.6 L198.4,209.9 L186.1,206.1 L180.9,214.1 L174.2,211.0 L153.4,185.7 L139.3,185.7 L139.3,189.9 L116.8,190.0 L86.8,175.9 L67.3,177.8 L56.0,162.6 L39.0,156.6 L8.3,98.5 L9.8,81.3 L7.3,73.5 L12.4,45.4 L6.0,18.3 L18.7,19.7 L23.0,29.4 L25.0,26.7 L21.0,10.0 Z";

/** Latitude and longitude to a point in the viewBox. */
export function project(lat: number, lon: number): { x: number; y: number } {
  return {
    x: PADDING + (lon - MIN_LON) * X_SCALE * SCALE,
    y: PADDING + (MAX_LAT - lat) * SCALE,
  };
}
